mapper.select:
SELECT tag.id, tag.name, tag.enabled FROM kb_document_tag tag WHERE EXISTS (
    SELECT 1 FROM kb_document_tag_relation relation
    JOIN kb_document d ON d.id = relation.document_id JOIN kb_doc_chunk c ON c.doc_id = d.id
    WHERE relation.tag_id = tag.id
    AND 
)
AND tag.name ILIKE #{pattern} ESCAPE '\'
AND tag.id > #{afterId}
ORDER BY tag.id LIMIT #{limit}
